suppressPackageStartupMessages({library(ggplot2);library(dplyr);library(readr);library(tidyr);library(patchwork)})
o<-normalizePath('8-Visualization/refinements/fig3_manuscript_revision_20261103_v4/supplement');old<-normalizePath('8-Visualization/refinements/fig3_focused_revision_20261103_v3');tt<-file.path(o,'source_data');ff<-file.path(o,'figures')
studycols<-read_csv('0-Data/qc/study_color_dictionary.csv',show_col_types=FALSE)
for(n in c('plot_cohort_dotplot.csv','main_epithelial_patient_grid.csv','shared_program_registry.csv'))file.copy(file.path(old,'source_data',n),file.path(tt,n),overwrite=TRUE)
for(n in c('method_concordance.csv','identity_sensitivity_contrasts.csv','plot_scoring_summary.csv','plot_identity_matched.csv'))file.copy(file.path(old,'supplement/source_data',n),file.path(tt,n),overwrite=TRUE)
reg<-read_csv(file.path(tt,'shared_program_registry.csv'),show_col_types=FALSE);ord<-reg$ProgramID
short<-c(Pattern_P1='P1',Pattern_P2='P2',Pattern_P3='P3',Pattern_P4='P4',Pattern_P5='P5',Pattern_P6='P6',WGCNA_MElightgreen='lightgreen · Fatty-acid / peroxisome',WGCNA_MEpink='pink · Catabolism',WGCNA_MEblack='black · Mitochondrial expression',WGCNA_MEcyan='cyan · Respiratory transport',WGCNA_MEbrown='brown · Morphogenesis',WGCNA_MEdarkgreen='darkgreen · Checkpoints',WGCNA_MEmagenta='magenta · Mitotic cycle',WGCNA_MEgreenyellow='greenyellow · Hypoxia / glycolysis',WGCNA_MEred='red · Glycosylation',WGCNA_MEdarkturquoise='darkturquoise · IFN',WGCNA_MEtan='tan · Muscle proliferation')
groups<-list(C1=c('Pattern_P1','Pattern_P2','WGCNA_MElightgreen','WGCNA_MEpink'),C2=c('Pattern_P3','WGCNA_MEblack','WGCNA_MEcyan','WGCNA_MEbrown','WGCNA_MEdarkgreen'),C3=c('Pattern_P4','Pattern_P5','Pattern_P6','WGCNA_MEmagenta','WGCNA_MEgreenyellow','WGCNA_MEred','WGCNA_MEdarkturquoise','WGCNA_MEtan'))
allord<-unlist(groups,use.names=FALSE);gmap<-setNames(rep(names(groups),lengths(groups)),allord)
base<-theme_classic(base_family='Arial',base_size=6)+theme(plot.title=element_text(size=7,face='bold'),plot.subtitle=element_text(size=5.5,colour='#555555'),plot.caption=element_text(size=5,hjust=0),axis.text=element_text(size=5.2,colour='#333333'),axis.title=element_text(size=5.5),strip.text=element_text(size=5.5,face='bold'),strip.background=element_rect(fill='#F1F2F3',colour=NA),legend.title=element_text(size=5.3),legend.text=element_text(size=5.2),legend.position='bottom',panel.spacing=grid::unit(1.4,'mm'),plot.margin=margin(3,2,2,5))
theme_set(base)
emit<-function(p,n,h){saveRDS(p,file.path(ff,paste0(n,'.rds')));svglite::svglite(file.path(ff,paste0(n,'.svg')),width=174/25.4,height=h/25.4);print(p);dev.off();cairo_pdf(file.path(ff,paste0(n,'.pdf')),width=174/25.4,height=h/25.4,family='Arial');print(p);dev.off();ragg::agg_png(file.path(ff,paste0(n,'.png')),width=174,height=h,units='mm',res=600,background='white');print(p);dev.off()}
fill<-function()scale_fill_gradientn(colours=c('#F4F4F4','#B7D7DA','#4B9CA8','#245366'),name='UCell',na.value='#E4E4E4')
a<-read_csv(file.path(tt,'plot_cohort_dotplot.csv'),show_col_types=FALSE)
a$ProgramID<-factor(a$ProgramID,levels=rev(allord));a$BulkGroup<-factor(gmap[as.character(a$ProgramID)],levels=names(groups));a$cohort<-factor(a$cohort,levels=c('GSE151530','GSE138709'));a$CellType<-factor(a$CellType,levels=unique(a$CellType))
write_csv(a,file.path(tt,'A_plot_values.csv'))
p<-ggplot(a,aes(CellType,ProgramID))+geom_tile(fill='#FAFAFA',colour='white')+geom_point(data=filter(a,!is.na(Score)),aes(fill=Score,size=NPatients),shape=21,stroke=.12)+geom_text(data=filter(a,is.na(Score)),label='–',size=5/ggplot2::.pt,colour='#999999')+facet_grid(BulkGroup~cohort,scales='free_y',space='free_y')+fill()+scale_size_area(max_size=2.3,breaks=c(2,4,6,8),name='Patients')+scale_y_discrete(labels=short)+scale_x_discrete(labels=function(x)gsub('Monocytes/macrophages','Mono / macrophage',x,fixed=TRUE))+labs(title='Fine cellular sources by tumor cohort',subtitle='C1/C2/C3: bulk-associated program groups; colour: score; size: independent patient support.',x=NULL,y=NULL)+theme(axis.line=element_blank(),axis.ticks=element_blank(),axis.text.x=element_text(angle=50,hjust=1),legend.key.height=grid::unit(1.5,'mm'),legend.box='horizontal',legend.box.spacing=grid::unit(0,'mm'))+guides(fill=guide_colourbar(barwidth=grid::unit(24,'mm'),barheight=grid::unit(1.8,'mm')),size=guide_legend(nrow=1))
emit(p,'SFigure4A_cohort_sources',80)
b<-read_csv(file.path(tt,'main_epithelial_patient_grid.csv'),show_col_types=FALSE);b$ProgramID<-factor(b$ProgramID,levels=rev(allord));b$BulkGroup<-factor(gmap[as.character(b$ProgramID)],levels=names(groups));pats<-unique(b$PatientKey);b$PatientKey<-factor(b$PatientKey,levels=pats);b$cohort<-factor(b$cohort,levels=c('GSE151530','GSE138709'));pl<-setNames(b$patient,b$PatientKey)
write_csv(b,file.path(tt,'B_plot_values.csv'))
p<-ggplot(b,aes(PatientKey,ProgramID))+geom_tile(aes(fill=Score),colour='white',linewidth=.15)+geom_text(data=filter(b,is.na(Score)),label='–',size=5/ggplot2::.pt,colour='#999999')+facet_grid(BulkGroup~cohort,scales='free',space='free')+fill()+scale_x_discrete(labels=pl)+scale_y_discrete(labels=short)+labs(title='Complete program profiles in tumor-tissue epithelium',subtitle='All 16 patients; 201/272 estimates. Eligible libraries averaged equally within each patient.',x=NULL,y=NULL,caption='Bulk-associated row groups are not cell or patient subtype labels. Grey/dash: unsupported; no positivity threshold.')+theme(axis.line=element_blank(),axis.ticks=element_blank(),axis.text.x=element_text(angle=45,hjust=1),legend.position='right',legend.key.height=grid::unit(2,'mm'))
emit(p,'SFigure4B_epithelial_full',75)
# Exact asset reuse: all alternative-scoring and matched eligibility contrasts retained.
for(ext in c('svg','pdf','png'))file.copy(file.path(old,'supplement/figures',paste0('S4_robustness.',ext)),file.path(ff,paste0('SFigure4C_robustness.',ext)),overwrite=TRUE)
writeLines(capture.output(sessionInfo()),file.path(o,'review/R_session_info.txt'))
